const $=id=>document.getElementById(id);let t=1,step=0,playing=false,last=null,raf;const fmt=n=>Number(n.toFixed(2)).toString();
function geometry(x){return {px:Math.min(2*x,4),py:Math.max(0,2*x-4),qy:x,base:x<=2?2*x:4-x,height:x<=2?x:4,area:x<=2?x*x:8-2*x}}
function lesson(){const pages=[`<div class="eyebrow">STEP 01 · 0 ≦ x ≦ 2</div><h2>PがAB上にいる間</h2><p>Pは毎秒2 cmだから<strong class="blue">AP＝2x cm</strong>。Qは毎秒1 cmだから<strong class="amber">BQ＝x cm</strong>だ。</p><p>底辺をAPにすると、高さはBQ。垂線の足Bが底辺APの延長上でも、同じ公式で求められるぞ。</p><div class="formula">y＝2x × x ÷ 2＝x²</div><p>PがBに着くのは4÷2＝<strong>2秒後</strong>。<br>だから範囲は<strong>0 ≦ x ≦ 2</strong>だ。</p>`,`<div class="eyebrow">STEP 02 · 2 ≦ x ≦ 4</div><h2>底辺をPQに変えてみよう</h2><p>PもQもBC上にいる。<br>BP＝2x−4、BQ＝xだから、<br><strong class="blue">PQ＝x−(2x−4)＝4−x cm</strong>。</p><p>底辺PQへの高さは、Aから直線BCまでの距離。<strong>いつでも4 cm</strong>だぞ。</p><div class="formula">y＝(4−x) × 4 ÷ 2<br>　＝−2x＋8</div><p>範囲は<strong>2 ≦ x ≦ 4</strong>。PがQに近づくほどPQが短くなり、面積も減るんだ。</p>`,`<div class="eyebrow">STEP 03 · 面積2になる時刻</div><h2>前半と後半、両方を調べよう</h2><p>前半は x²＝2。時間は負にならないから<br><strong>x＝√2</strong>（約1.414秒）。<br>後半は −2x＋8＝2 だから <strong>x＝3</strong>。</p><div class="formula">答え：x＝√2、3</div><p>√2は0〜2、3は2〜4に入っているな。グラフのy＝2との交点も２つあるぞ！</p><form id="quiz"><label for="answer">後半で面積が1 cm²になるのは？</label><div class="answerline"><input id="answer" type="number" step="any" required aria-label="面積1になる後半の時刻"> 秒 <button class="primary" type="submit">確かめる</button></div></form><p id="feedback" aria-live="polite"></p>`];$('lesson').innerHTML=pages[step];if(step===2)$('quiz').onsubmit=e=>{e.preventDefault();const ok=Number($('answer').value)===3.5;$('feedback').textContent=ok?'正解だ！ −2×3.5＋8＝1 cm²になるぞ。':'−2x＋8＝1を解いてみよう。答えは2秒から4秒の間だぞ。';if(ok)setTime(3.5)}}
function render(){const g=geometry(t),px=230+70*g.px,py=325-70*g.py,qy=325-70*g.qy;const put=(id,a)=>Object.entries(a).forEach(([k,v])=>$(id).setAttribute(k,v));put('triangle',{points:`230,325 ${px},${py} 510,${qy}`});put('pDot',{cx:px,cy:py});put('qDot',{cx:510,cy:qy});put('base',{d:t<=2?`M230 325H${px}`:`M510 ${py}V${qy}`});put('height',{d:t<=2?`M${px} 325H510V${qy}`:'M230 325H510'});put('rightAngle',{d:t>0&&t<4?'M498 325v-12h12':''});put('pLabel',{x:t<=2?px-8:480,y:t<=2?353:py+6});put('qLabel',{x:526,y:qy+6});$('pLabel').textContent=t===0?'':t===4?'':'P';$('qLabel').textContent=t===0?'Q・B':t===4?'':'Q';$('aLabel').textContent=t===0?'A・P':'A';$('bLabel').style.display=t===0||t===2?'none':'';$('cLabel').textContent=t===4?'C・P・Q':'C';if(t===2)$('pLabel').textContent='P・B';put('baseLabel',{x:t<=2?(230+px)/2-40:555,y:t<=2?378:(py+qy)/2+7});$('baseLabel').textContent=t===0?'':`${t<=2?'AP':'PQ'} ${fmt(g.base)} cm`;put('heightLabel',{x:t<=2?600:370,y:t<=2?(325+qy)/2-14:350});$('heightLabel').textContent=t===0?'':`高さ ${fmt(g.height)} cm`;$('time').textContent=t.toFixed(2);$('slider').value=t;$('baseTitle').textContent=t<=2?'底辺 AP':'底辺 PQ';$('heightTitle').textContent=t<=2?'高さ BQ':'高さ AB';$('baseValue').textContent=fmt(g.base);$('heightValue').textContent=fmt(g.height);$('areaValue').textContent=fmt(g.area);$('exactTime').textContent=Math.abs(t-Math.SQRT2)<1e-10?'正確な時刻は √2秒（約1.414秒）。面積はちょうど2 cm²だぞ。':'';$('liveFormula').textContent=t<=2?'PはAB上：y＝x² （0 ≦ x ≦ 2）':'PとQはBC上：y＝−2x＋8 （2 ≦ x ≦ 4）';const gx=45+80*t,gy=190-40*g.area;put('dot',{cx:gx,cy:gy});put('guide',{d:`M45 ${gy}H${gx}V190`})}
function stop(){playing=false;cancelAnimationFrame(raf);$('play').textContent='▶ 再生'}function setTime(n){stop();t=n;render()}function frame(now){if(!playing)return;if(last!==null)t=Math.min(4,t+(now-last)/1000);last=now;render();if(t>=4)stop();else raf=requestAnimationFrame(frame)}
$('slider').oninput=e=>setTime(Number(e.target.value));$('reset').onclick=()=>setTime(0);$('corner').onclick=()=>setTime(2);$('firstRoot').onclick=()=>setTime(Math.SQRT2);$('secondRoot').onclick=()=>setTime(3);$('play').onclick=()=>{if(playing)return stop();if(t>=4)t=0;playing=true;last=null;$('play').textContent='Ⅱ 一時停止';raf=requestAnimationFrame(frame)};document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.step);document.querySelectorAll('[data-step]').forEach(btn=>{const active=Number(btn.dataset.step)===step;btn.classList.toggle('active',active);btn.setAttribute('aria-pressed',active)});lesson();if(step===0&&t>2)setTime(1);if(step===1&&t<=2)setTime(3)});window.addEventListener('pagehide',stop);lesson();render();
